// Numeric tokenizer
class NumericTokenizer(
  precision: Int = 6,
  formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[AnyVal] {

  def tokenize(value: AnyVal): Token = {
    val strValue = value match {
      case d: Double => f"$d%.${precision}f"
      case f: Float => f"$f%.${precision}f"
      case bd: BigDecimal => bd.setScale(precision, BigDecimal.RoundingMode.HALF_UP).toString
      case i: Int => i.toString
      case l: Long => l.toString
      case _ => value.toString
    }

    Token(strValue, TokenType.NUMERIC, Map("original_type" -> value.getClass.getSimpleName))
  }
}

object NumericTokenizer {
  def apply(precision: Int = 6, formatOptions: Map[String, Any] = Map.empty): NumericTokenizer =
    new NumericTokenizer(precision, formatOptions)
}

// Temporal tokenizer
class TemporalTokenizer(formatStr: Option[String] = None) extends BaseTokenizer[Any] {
  private val ISO_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
  private val DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd")

  def tokenize(value: Any): Token = {
    val (strValue, formatter) = value match {
      case dt: LocalDateTime =>
        val fmt = formatStr.map(DateTimeFormatter.ofPattern).getOrElse(ISO_FORMAT)
        (dt.format(fmt), fmt)
      case d: LocalDate =>
        val fmt = formatStr.map(DateTimeFormatter.ofPattern).getOrElse(DATE_FORMAT)
        (d.format(fmt), fmt)
      case _ =>
        throw new IllegalArgumentException(s"Unsupported temporal type: ${value.getClass}")
    }

    Token(strValue, TokenType.TEMPORAL)
  }
}

object TemporalTokenizer {
  def apply(formatStr: Option[String] = None): TemporalTokenizer =
    new TemporalTokenizer(formatStr)
}

// ============================================================================
// Universal Tokenizer with Type-Based Dispatch
// ============================================================================

class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  def tokenize(value: Any): Token = value match {
    case null => Token("NULL", TokenType.NULL)
    case t: Tokenizable => Token(t.toToken, TokenType.STRUCTURED)
    case s: String => stringTokenizer.tokenize(s)
    case i: Int => numericTokenizer.tokenize(i)
    case l: Long => numericTokenizer.tokenize(l)
    case f: Float => numericTokenizer.tokenize(f)
    case d: Double => numericTokenizer.tokenize(d)
    case bd: BigDecimal => numericTokenizer.tokenize(bd)
    case dt: LocalDateTime => temporalTokenizer.tokenize(dt)
    case d: LocalDate => temporalTokenizer.tokenize(d)
    case _ => Token(value.toString, TokenType.STRING, Map("fallback" -> true))
  }
}

object UniversalTokenizer {
  def apply(): UniversalTokenizer = new UniversalTokenizer()
}

// ============================================================================
// Complex Nested Generics - Token Registry
// ============================================================================

class TokenRegistry[T] {
  private var registry: Map[String, TokenContainer[T]] = Map.empty
  private var handlers: List[T => Option[Token]] = List.empty

  def register(key: String, container: TokenContainer[T]): Unit = {
    registry = registry + (key -> container)
  }

  def addHandler(handler: T => Option[Token]): Unit = {
    handlers = handlers :+ handler
  }

  def process(key: String): List[Option[Token]] = {
    registry.get(key) match {
      case None => List.empty
      case Some(container) =>
        container.getAll.map { item =>
          handlers.view.flatMap(_(item)).headOption
        }.toList
    }
  }
}

