// Monadic Token Wrapper
// ============================================================================

case class TokenFunctor[T](value: T) {
  def map[U](func: T => U): TokenFunctor[U] = TokenFunctor(func(value))

  def flatMap[U](func: T => TokenFunctor[U]): TokenFunctor[U] = func(value)

  def getOrElse(default: T): T = if (value != null) value else default
}

case class TokenMonad[T](value: T) extends TokenFunctor[T](value) {
  def ap[U](funcWrapped: TokenMonad[T => U]): TokenMonad[U] = {
    TokenMonad(funcWrapped.value(value))
  }
}

object TokenMonad {
  def pure[T](value: T): TokenMonad[T] = TokenMonad(value)
}

