// Recursive JSON type
sealed trait JsonValue
case class JsonString(value: String) extends JsonValue
case class JsonNumber(value: Double) extends JsonValue
case class JsonBool(value: Boolean) extends JsonValue
case object JsonNull extends JsonValue
case class JsonArray(values: List[JsonValue]) extends JsonValue
case class JsonObject(fields: Map[String, JsonValue]) extends JsonValue

class JsonTokenizer(pretty: Boolean = false) {

  def tokenize(value: JsonValue): Token = {
    val jsonStr = jsonToString(value, if (pretty) 0 else -1)
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  private def jsonToString(value: JsonValue, indent: Int): String = value match {
    case JsonString(s) => s"\"$s\""
    case JsonNumber(n) => n.toString
    case JsonBool(b) => b.toString
    case JsonNull => "null"
    case JsonArray(values) =>
      val items = values.map(v => jsonToString(v, if (indent >= 0) indent + 2 else -1))
      if (indent >= 0) {
        val spacing = " " * (indent + 2)
        val endSpacing = " " * indent
        s"[\n$spacing${items.mkString(s",\n$spacing")}\n$endSpacing]"
      } else {
        s"[${items.mkString(",")}]"
      }
    case JsonObject(fields) =>
      val items = fields.map { case (k, v) =>
        val valStr = jsonToString(v, if (indent >= 0) indent + 2 else -1)
        s"\"$k\":$valStr"
      }
      if (indent >= 0) {
        val spacing = " " * (indent + 2)
        val endSpacing = " " * indent
        s"{\n$spacing${items.mkString(s",\n$spacing")}\n$endSpacing}"
      } else {
        s"{${items.mkString(",")}}"
      }
  }

  def tokenizePath(value: JsonValue, path: String): Option[Token] = {
    val parts = path.split("\\.")

    def navigate(current: JsonValue, remaining: List[String]): Option[JsonValue] = remaining match {
      case Nil => Some(current)
      case part :: rest => current match {
        case JsonObject(fields) => fields.get(part).flatMap(navigate(_, rest))
        case JsonArray(values) =>
          Try(part.toInt).toOption
            .filter(idx => idx >= 0 && idx < values.length)
            .flatMap(idx => navigate(values(idx), rest))
        case _ => None
      }
    }

    navigate(value, parts.toList).map(tokenize)
  }
}

object JsonTokenizer {
  def apply(pretty: Boolean = false): JsonTokenizer = new JsonTokenizer(pretty)
}

